/**
 * 정기인사 포탈 — 데이터 모델 v3 (실 데이터 파이프라인)
 * 생성일: 2026-04-10 15:10
 * 소스: 사원명부(260304) + 25 종합평가 최종결과
 * 대상: 1287명 (Lv 보유 PL/Non-PL/매니저)
 *
 * ⚠️ 개인정보 익명화 완료: 이름=합성, 사번=해시ID
 *    법인·부서·등급·점수 분포는 실 데이터 기반
 *
 * 평가 프로세스:
 *   1차 자기평가 → 관리자 1차 조정 (기초등급 A/B/C)
 *   → Calibration Session → 최종 7등급 (S/A+/A/B+/B/C/D) 분화
 *
 * CEI 3축: 기여도(C)·전문성(E)·영향력(I) 각 0~4점 범위
 * 인사 5유형: 승진·승급·승격·이동·직책해제
 * 직군: PL(영업) / Non-PL(일반) / 매니저
 */

